  "カタログ|12": {"jp":"このカタログをもらってもいいですか。","r":"kono katarogu o moratte mo ii desu ka.","de":"Darf ich diesen Katalog mitnehmen?","note":"～てもいいですか um Erlaubnis bitten."},
  "エレベーター|12": {"jp":"エレベーターは あちらです。","r":"erebētā wa achira desu.","de":"Der Aufzug ist dort drüben.","note":"Langer Vokal: erebētā."},
  "つくります|12": {"jp":"ここでケーキを作ってもいいですか。","r":"koko de keeki o tsukutte mo ii desu ka.","de":"Darf ich hier einen Kuchen machen?","note":"～てもいいですか fragt nach Erlaubnis."},
  "たのしい|12": {"jp":"りょうの生活は楽しいです。","r":"ryou no seikatsu wa tanoshii desu.","de":"Das Wohnheimleben ist schön.","note":"い-Adjektiv; subjektives 'angenehm'."},
  "すてき|12": {"jp":"すてきな車ですね。","r":"suteki na kuruma desu ne.","de":"Was für ein tolles Auto!","note":"な-Adjektiv; vor Nomen すてきな."},
  "よる|12": {"jp":"よる はやく ねます。","r":"yoru hayaku nemasu.","de":"Nachts gehe ich früh ins Bett.","note":"よる = Nacht."},
  "にく|12": {"jp":"ばんごはんに にくを 食べます。","r":"bangohan ni niku o tabemasu.","de":"Zum Abendessen esse ich Fleisch.","note":"肉 = Fleisch."},
  "とりにく|12": {"jp":"とりにくとぎゅうにくとどちらがすきですか。","r":"Toriniku to gyūniku to dochira ga suki desu ka.","de":"Was magst du lieber, Hühner- oder Rindfleisch?","note":"とり (Vogel) + にく (Fleisch)."},
  "ぎゅうにく|12": {"jp":"やすみのひにぎゅうにくをかって、バーベキューをします。","r":"Yasumi no hi ni gyūniku o katte, bābekyū o shimasu.","de":"Am freien Tag kaufe ich Rindfleisch und grille.","note":"ぎゅう (Rind) + にく (Fleisch)."},
