  "ぎゅうにゅう|12": {"jp":"まいあさ ぎゅうにゅうを 飲みます。","r":"maiasa gyuunyuu o nomimasu.","de":"Jeden Morgen trinke ich Milch.","note":"牛乳; lange Vokale gyuu/nyuu."},
  "まっちゃ|12": {"jp":"にほんでまっちゃをかいました。","r":"Nihon de matcha o kaimashita.","de":"In Japan habe ich Matcha gekauft.","note":"Grüntee-Pulver."},
  "きもの|12": {"jp":"きょうとで きものを かった。","r":"Kyouto de kimono o katta.","de":"In Kyoto habe ich einen Kimono gekauft.","note":"かった = Plain-Vergangenheit."},
