  "びょうき|12": {"jp":"びょうきですから、しごとを やすまなければ なりません。","r":"byouki desu kara, shigoto o yasumanakereba narimasen.","de":"Weil ich krank bin, muss ich der Arbeit fernbleiben.","note":"びょうき = Krankheit (Nomen)."},
  "えもじ|12": {"jp":"よくえもじをつかいますか。","r":"Yoku emoji o tsukaimasu ka.","de":"Benutzt du oft Emojis?","note":"え (Bild) + もじ (Zeichen)."},
