  /* Lektion 13 */
  "きります|13": {"jp":"ナイフでパンを切ります。","r":"naifu de pan o kirimasu.","de":"Ich schneide das Brot mit dem Messer.","note":"Werkzeug mit で; 切ります ist V. I."},
  "きます|13": {"jp":"あの 青い セーターを 着て いる 人は ミラーさんです。","r":"ano aoi seetaa o kite iru hito wa miraa san desu.","de":"Die Person, die den blauen Pullover trägt, ist Herr Miller.","note":"着て いる: Relativsatz, der 人 näher bestimmt."},
  "のります|13": {"jp":"東京駅で新幹線に乗ります。","r":"Tookyoo-eki de shinkansen ni norimasu.","de":"Am Bahnhof Tokyo steige ich in den Shinkansen.","note":"乗ります mit Partikel に."},
  "しにます|13": {"jp":"このはなはしにました。","r":"Kono hana wa shinimashita.","de":"Diese Blume ist eingegangen.","note":"Einziges Verb auf ぬ: しんで, しなない."},
  "うんどうします|13": {"jp":"かぜをひいていますから、きょうはうんどうしないでください。","r":"Kaze o hiite imasu kara, kyō wa undō shinai de kudasai.","de":"Du bist erkältet, mach heute bitte keinen Sport.","note":"うんどう = Bewegung, Sport."},
  "おはなみ|13": {"jp":"ともだちと おはなみを します。","r":"tomodachi to ohanami o shimasu.","de":"Ich mache mit Freunden eine Kirschblütenschau.","note":"お花見をします (mit します)."},
  "おはなみします|13": {"jp":"さくらのしたでおはなみします。","r":"Sakura no shita de ohanami shimasu.","de":"Wir machen Hanami unter den Kirschbäumen.","note":"Kirschblütenfest im Frühling."},
  "ぬぎます|13": {"jp":"ここで くつを ぬがなければ なりません。","r":"koko de kutsu o nuganakereba narimasen.","de":"Hier muss man die Schuhe ausziehen.","note":"う-Verb: ない-Form ぬがない."},
  "くつ|13": {"jp":"くつの うりばは にかいです。","r":"kutsu no uriba wa nikai desu.","de":"Die Schuhabteilung ist im 2. Stock.","note":"N の うりば = Abteilung für N."},
  "ひきます|13": {"jp":"わたしは ピアノを ひく ことが できます。","r":"watashi wa piano o hiku koto ga dekimasu.","de":"Ich kann Klavier spielen.","note":"Wörterbuchform ひく + ことができます."},
  "あぶない|13": {"jp":"ここは あぶないですから、はいらないで ください。","r":"koko wa abunai desu kara, hairanaide kudasai.","de":"Hier ist es gefährlich, gehen Sie bitte nicht hinein.","note":"い-Adjektiv: あぶない."},
  "きんえん|13": {"jp":"ここは きんえんですから、たばこを すわないで ください。","r":"koko wa kin'en desu kara, tabako o suwanaide kudasai.","de":"Hier ist Rauchverbot, rauchen Sie bitte nicht.","note":"きんえん = Nomen: Rauchverbot."},
  "ひ|13": {"jp":"ひをけしてください。","r":"Hi o keshite kudasai.","de":"Bitte lösch das Feuer.","note":"火 = Feuer; ひをけします = Feuer löschen."},
  "しんぱいします|13": {"jp":"だいじょうぶですから、しんぱいしないで ください。","r":"daijoubu desu kara, shinpai shinaide kudasai.","de":"Es ist in Ordnung, machen Sie sich bitte keine Sorgen.","note":"します-Verb: ない-Form しんぱいしない."},
  "おぼえます|13": {"jp":"ことばを たくさん おぼえなければ なりません。","r":"kotoba o takusan oboenakereba narimasen.","de":"Ich muss mir viele Vokabeln merken.","note":"おぼえます ist V. II: ない-Form おぼえない."},
  "わすれます|13": {"jp":"パスポートを わすれないで ください。","r":"pasupooto o wasurenaide kudasai.","de":"Vergessen Sie bitte nicht Ihren Reisepass.","note":"～ないでください = höfliche Bitte, etwas nicht zu tun."},
  "おします|13": {"jp":"このボタンを押して、お金を入れます。","r":"kono botan o oshite, okane o iremasu.","de":"Ich drücke diesen Knopf und werfe Geld ein.","note":"て-Form für Reihenfolge der Handlungen."},
  "ボタン|13": {"jp":"このボタンを押して、お金を下ろします。","r":"kono botan o oshite, okane o oroshimasu.","de":"Ich drücke diesen Knopf und hebe Geld ab.","note":"ボタンを押します = einen Knopf drücken."},
  "ニュース|13": {"jp":"毎晩ニュースを見ています。","r":"maiban nyuusu o mite imasu.","de":"Ich schaue jeden Abend die Nachrichten.","note":"毎晩 + ～ています für Gewohnheit."},
  "ざっし|13": {"jp":"これはにほんのざっしです。","r":"Kore wa Nihon no zasshi desu.","de":"Das ist eine japanische Zeitschrift.","note":"ざっし wird mit kleinem っ (Doppelkonsonant) ausgesprochen: 'zasshi'."},
  "おくれます|13": {"jp":"じゅぎょうにおくれないでください。","r":"Jugyō ni okurenai de kudasai.","de":"Komm bitte nicht zu spät zum Unterricht.","note":"Wofür man zu spät ist: に."},
